                move.w  #$9F,$2E(a0)

Obj_CNZMinibossCloseGo:
                move.b  #6,routine(a0)
                move.l  #Obj_CNZMinibossChangeDir,$34(a0)
                bclr    #3,$38(a0)
                lea     (PalSPtr_CNZMinibossNormal).l,a1
                lea     (Palette_rotation_data).w,a2
                move.l  (a1)+,(a2)+
                move.l  (a1)+,(a2)+
                clr.w   (a2)
                move.l  #CNZMiniboss_MakeTimedSparks,(Palette_rotation_custom).w
                rts
