loc_6DCB0:
                moveq   #-$10,d3                        ; If moving to the left
                jsr     (ObjCheckLeftWallDist).l
                tst.w   d1
                bmi.w   loc_6DD4C                       ; Reverse direction if wall was hit
                move.w  x_pos(a0),d0
                subi.w  #$10,d0
                cmpi.w  #$3200,d0
                blo.w   loc_6DD8E                       ; Reverse direction if edge of screen is hit
