loc_6DD4C:
                lea     Child1_CNZBounceEffect(pc),a2
                jsr     (CreateChild1_Normal).l
                bne.s   loc_6DD64
                tst.w   x_vel(a0)
                bmi.s   loc_6DD64
                bset    #0,render_flags(a1)

loc_6DD64:
                moveq   #$10,d0
                neg.w   x_vel(a0)                       ; Change direction
                bmi.s   loc_6DD6E
                neg.w   d0

loc_6DD6E:
                add.w   x_pos(a0),d0
                cmpi.w  #$3200,d0
                bls.s   locret_6DD8C
                cmpi.w  #$3380,d0
