loc_6DD8E:
                neg.w   x_vel(a0)                       ; Simple direction switch
                rts
; ---------------------------------------------------------------------------

loc_6DD94:
                move.w  x_pos(a0),d0
                moveq   #8,d1
                neg.w   y_vel(a0)
                bmi.s   loc_6DDA2
                neg.w   d1

loc_6DDA2:
                add.w   y_pos(a0),d1
                cmpi.w  #$3200,d0
                bls.s   locret_6DD8C
                cmpi.w  #$3380,d0
                bhs.s   locret_6DD8C
                cmpi.w  #$300,d1
                blo.s   locret_6DD8C
                cmpi.w  #$3380,d1
                bhs.s   locret_6DD8C
                move.w  d0,(Events_bg+$00).w            ; Move X/Y positions into special variables see above
