loc_6DDD2:
                lea     Child1_CNZMinibossExplosion(pc),a2
                jsr     (CreateChild1_Normal).l
                move.b  #6,subtype(a1)
                clr.b   collision_flags(a0)
                jsr     (Displace_PlayerOffObject).l
