                bne.s   loc_6DEB6
                btst    #6,$38(a1)
                beq.w   Obj_CNZMinibossCoil             ; If parent closes up
                jmp     (Add_SpriteToCollisionResponseList).l
; ---------------------------------------------------------------------------

loc_6DEDE:
                move.l  #loc_6DEEC,(a0)
                move.b  #$AA,collision_flags(a0)
                rts
; ---------------------------------------------------------------------------

loc_6DEEC:
                jsr     (Refresh_ChildPosition).l
                jmp     (Add_SpriteToCollisionResponseList).l
