CNZMiniboss_MoveDown:
                move.w  (Events_bg+$04).w,d0
                cmp.w   $3C(a0),d0
                beq.s   locret_6E198
                move.w  d0,$3C(a0)
                move.b  routine(a0),$42(a0)
                move.b  #$E,routine(a0)
                move.b  #$1F,$43(a0)

locret_6E198:
                rts
