Obj_WaitForParent:
                movea.w parent3(a0),a1
                btst    #5,$38(a1)
                bne.w   loc_83EC2
                tst.l   (a1)
                beq.w   loc_83EC2
                move.w  x_pos(a1),x_pos(a0)
                move.w  y_pos(a1),y_pos(a0)
                jmp     Obj_Wait(pc)
; ---------------------------------------------------------------------------

Obj_BossExpControl1:
                move.b  $39(a0),d0
                bmi.s   loc_83E7E                       ; If negative, explosions are constantly created every three frames
                subq.b  #1,d0
                move.b  d0,$39(a0)                      ; Otherwise, continue making explosions until timer runs out
                beq.s   loc_83EC2

loc_83E7E:
                move.w  #2,$2E(a0)

; =============== S U B R O U T I N E =======================================

sub_83E84:
                lea     Child6_MakeBossExplosion1(pc),a2
                jsr     CreateChild6_Simple(pc)
                bne.w   locret_83EC0

loc_83E90:
                jsr     (Random_Number).l               ; Offset the explosion by a random amount capped by an effective range
                moveq   #0,d1
                move.b  $3A(a0),d1
                move.w  d1,d2
                add.w   d2,d2
                subq.w  #1,d2
                and.w   d2,d0
                sub.w   d1,d0
                add.w   d0,x_pos(a1)
                swap    d0
                moveq   #0,d1
                move.b  $3B(a0),d1
                move.w  d1,d2
                add.w   d2,d2
                subq.w  #1,d2
                and.w   d2,d0
                sub.w   d1,d0
                add.w   d0,y_pos(a1)

locret_83EC0:
                rts
; End of function sub_83E84

