                bne.s   .end
                move.w  a0,parent3(a1)
                move.l  mappings(a0),mappings(a1)
                move.w  art_tile(a0),art_tile(a1)
                move.l  (a2),(a1)
                move.b  d2,subtype(a1)
                move.w  x_pos(a0),x_pos(a1)
                move.w  y_pos(a0),y_pos(a1)
                addq.w  #2,d2
                dbf     d6,.loop
                moveq   #0,d0

                .end:
                rts
; End of function CreateChild6_Simple

